; Tile library, variant 3x2_ptr, see demo.inc
; Tiles 3x2 characters, pointer version (TILE_SMC = 0: ROM-capable).
; Build: vcc asm tiles_demo_3x2_ptr.asm --target plus4 --cpu 7501 -o <output>.prg, or vcc build in the folder; test: vcc test --backend vice.
; The files of this group are generated by tools/gen_tiles_demo.py.
.const DEMO_SET = 3                 ; tile size/data set: 3 = 3x2 (data_3x2.inc), 2 = 2x2 (data_2x2.inc)
.const TILE_SMC = 0                 ; 0 = pointer version, 1 = self-modifying code
.include "demo.inc"
